mapper.select:
/* saleson.shop.tempprocess.TempProcessMapper.getTempAllOrderCountByParamForManager */ SELECT /*+ USE_MERGE(O, OSI, CHK, S) */ COUNT(1) FROM OP_ORDER_ITEM_HOLD OI INNER JOIN MIG_OP_ORDER O ON OI.ORDER_CODE = O.ORDER_CODE AND OI.ORDER_SEQUENCE = O.ORDER_SEQUENCE AND O.DATA_STATUS_CODE = '1' INNER JOIN OP_ORDER_SHIPPING_INFO OSI ON OI.ORDER_CODE = OSI.ORDER_CODE AND OI.ORDER_SEQUENCE = OSI.ORDER_SEQUENCE AND OI.SHIPPING_INFO_SEQUENCE = OSI.SHIPPING_INFO_SEQUENCE INNER JOIN ( SELECT T_B.ORDER_CODE , CASE WHEN MAX(ORDER_AMT_TOT) - MAX(RCP_WAIT_AMT_TOT) - MAX(CANCEL_AMT_TOT) = MAX(CNTR_USE_POINT_TOT) THEN 'Y' ELSE 'N' END MATCH_YN FROM ( SELECT ORDER_CODE ORDER_CODE , 0 CNTR_USE_POINT_TOT , SUM(SALE_PRICE * QUANTITY + ETC_AMT) ORDER_AMT_TOT , SUM(CASE WHEN ORDER_STATUS = '0' THEN SALE_PRICE * QUANTITY + ETC_AMT ELSE 0 END ) RCP_WAIT_AMT_TOT , SUM(CASE WHEN ORDER_STATUS IN ('65', '75') THEN SALE_PRICE * QUANTITY + ETC_AMT ELSE 0 END ) CANCEL_AMT_TOT FROM ( SELECT * FROM OP_ORDER_ITEM WHERE 1=1 AND ORDER_CODE LIKE 'AB%' UNION ALL SELECT * FROM OP_ORDER_ITEM_HOLD H WHERE 1=1 AND NOT EXISTS (SELECT 1 FROM OP_ORDER_ITEM OI WHERE OI.ORDER_CODE = H.ORDER_CODE AND OI.ORDER_SEQUENCE = H.ORDER_SEQUENCE AND OI.ITEM_SEQUENCE = H.ITEM_SEQUENCE ) ) T_A WHERE 1=1 GROUP BY T_A.ORDER_CODE UNION ALL SELECT ORDER_CODE ORDER_CODE , SUM(CNTR_USE_POINT) CNTR_USE_POINT_TOT , 0 ORDER_AMT_TOT , 0 RCP_WAIT_AMT_TOT , 0 CANCEL_AMT_TOT FROM G_CNTR_USE_POINT -- 개발 WHERE 1=1 AND ORDER_CODE LIKE 'AB%' GROUP BY ORDER_CODE ) T_B GROUP BY T_B.ORDER_CODE ) CHK ON OI.ORDER_CODE = CHK.ORDER_CODE INNER JOIN OP_SELLER S ON OI.SELLER_ID = S.SELLER_ID LEFT JOIN OP_USER U ON OI.USER_ID = U.USER_ID
AND OI.SELLER_ID = #{sellerId} AND OI.DELIVERY_TYPE = '2'
AND OI.ORDER_STATUS IN
#{status}
AND OI.SELLER_ID = #{sellerId}
AND OI.SELLER_ID > #{sellerId}
AND OI.DELIVERY_TYPE = #{deliveryType}
AND OI.ORDER_STATUS IN
#{status}
AND OI.ORDER_CODE IN
#{orderCode}
AND OI.ORDER_CODE = #{orderCode}
AND OI.ORDER_SEQUENCE = #{orderSequence}
AND OI.ITEM_SEQUENCE = #{itemSequence}
AND OI.ORDER_STATUS IN
#{orderStatus}
AND OI.ORDER_STATUS = #{orderStatus}
AND OI.CANCEL_FLAG = #{cancelFlag}
AND OI.USER_ID = #{userId} AND OI.GUEST_FLAG = 'N'
AND OI.GUEST_FLAG = 'Y' AND O.BUYER_NAME = #{guestUserName} AND O.MOBILE = #{guestPhoneNumber}
AND S.LOCGOV_CODE = #{locgovCode}
AND S.LOCGOV_CODE LIKE CONCAT(SUBSTR(#{upperLocgovCode}, 0, 2), '%')
AND OI.ITEM_NAME LIKE CONCAT('%', #{itemName}, '%')
AND DATE_FORMAT(OI.CREATED_DATE, '%Y%m%d%H') BETWEEN CONCAT(#{searchStartDate},#{searchStartDateTime}) AND CONCAT(#{searchEndDate},#{searchEndDateTime})
AND DATE_FORMAT(O.CREATED_DATE, '%Y%m%d%H') BETWEEN CONCAT(#{searchStartDate},#{searchStartDateTime}) AND CONCAT(#{searchEndDate},#{searchEndDateTime})
AND DATE_FORMAT(#{searchDateType}, '%Y%m%d') BETWEEN #{searchStartDate} AND #{searchEndDate}
AND U.USER_NAME LIKE CONCAT('%', #{query}, '%')
AND OI.USER_ID IN ( SELECT USER_ID FROM OP_USER WHERE LOGIN_ID LIKE CONCAT('%', #{query},'%') )
AND ( REPLACE(OSI.PHONE, '-', '') LIKE CONCAT(REPLACE(#{query}, '-', ''), '%') OR REPLACE(OSI.MOBILE, '-', '') LIKE CONCAT(REPLACE(#{query}, '-', ''), '%') )
AND OSI.RECEIVE_NAME LIKE CONCAT('%', #{query},'%')
AND OI.ITEM_NAME LIKE CONCAT('%', #{query},'%')
AND (OI.ITEM_CODE = #{query} OR OI.ITEM_USER_CODE = #{query})
AND OSI.EMAIL LIKE CONCAT(#{query}, '%')
AND OI.ORDER_CODE LIKE CONCAT('%', #{query} , '%')
AND S.COMPANY_NAME LIKE CONCAT('%', #{query},'%')
AND S.LOCGOV_CODE = #{shLocgovCode}
AND S.LOCGOV_CODE IN ( SELECT LOCGOV.LOCGOV_CODE FROM G_LOCGOV LOCGOV WHERE LOCGOV.UPPER_LOCGOV_CODE = #{shWdr} )
AND CHK.MATCH_YN = 'Y' AND OI.FILLER10 = 'N'
AND NOT EXISTS (SELECT 1 FROM OP_ORDER_ITEM T WHERE T.ORDER_CODE = OI.ORDER_CODE AND T.ORDER_SEQUENCE = OI.ORDER_SEQUENCE AND T.ITEM_SEQUENCE = OI.ITEM_SEQUENCE)
AND OI.HOLD_CONFIRM_STATUS IN
#{status}

/* saleson.shop.tempprocess.TempProcessMapper.getTempAllOrderListByParamForManager */ SELECT OI.*, OI.ORDER_CODE || '-' || OI.FILLER5 AS RC_ORDER_CODE, U.USER_NAME, L.UPPER_LOCGOV_NM || ' ' || L.LOCGOV_NM AS LOCGOV_NM FROM (
SELECT /*+ USE_MERGE(O, OSI, CHK, S) */ O.LOGIN_ID, O.BUYER_NAME, OI.*, OSI.RECEIVE_NAME, IFNULL(S.SELLER_NAME, '') AS SELLER_NAME, IFNULL(S.COMPANY_NAME, '') AS COMPANY_NAME, OI.USER_ID AS OI_USER_ID, CHK.MATCH_YN FROM OP_ORDER_ITEM_HOLD OI INNER JOIN MIG_OP_ORDER O ON OI.ORDER_CODE = O.ORDER_CODE AND OI.ORDER_SEQUENCE = O.ORDER_SEQUENCE AND O.DATA_STATUS_CODE = '1' INNER JOIN OP_ORDER_SHIPPING_INFO OSI ON OI.ORDER_CODE = OSI.ORDER_CODE AND OI.ORDER_SEQUENCE = OSI.ORDER_SEQUENCE AND OI.SHIPPING_INFO_SEQUENCE = OSI.SHIPPING_INFO_SEQUENCE INNER JOIN ( SELECT T_B.ORDER_CODE , CASE WHEN MAX(ORDER_AMT_TOT) - MAX(RCP_WAIT_AMT_TOT) - MAX(CANCEL_AMT_TOT) = MAX(CNTR_USE_POINT_TOT) THEN 'Y' ELSE 'N' END MATCH_YN FROM ( SELECT ORDER_CODE ORDER_CODE , 0 CNTR_USE_POINT_TOT , SUM(SALE_PRICE * QUANTITY + ETC_AMT) ORDER_AMT_TOT , SUM(CASE WHEN ORDER_STATUS = '0' THEN SALE_PRICE * QUANTITY + ETC_AMT ELSE 0 END ) RCP_WAIT_AMT_TOT , SUM(CASE WHEN ORDER_STATUS IN ('65', '75') THEN SALE_PRICE * QUANTITY + ETC_AMT ELSE 0 END ) CANCEL_AMT_TOT FROM ( SELECT * FROM OP_ORDER_ITEM WHERE 1=1 AND ORDER_CODE LIKE 'AB%' UNION ALL SELECT * FROM OP_ORDER_ITEM_HOLD H WHERE 1=1 AND NOT EXISTS (SELECT 1 FROM OP_ORDER_ITEM OI WHERE OI.ORDER_CODE = H.ORDER_CODE AND OI.ORDER_SEQUENCE = H.ORDER_SEQUENCE AND OI.ITEM_SEQUENCE = H.ITEM_SEQUENCE ) ) T_A WHERE 1=1 GROUP BY T_A.ORDER_CODE UNION ALL SELECT ORDER_CODE ORDER_CODE , SUM(CNTR_USE_POINT) CNTR_USE_POINT_TOT , 0 ORDER_AMT_TOT , 0 RCP_WAIT_AMT_TOT , 0 CANCEL_AMT_TOT FROM G_CNTR_USE_POINT -- 개발 WHERE 1=1 AND ORDER_CODE LIKE 'AB%' GROUP BY ORDER_CODE ) T_B GROUP BY T_B.ORDER_CODE ) CHK ON OI.ORDER_CODE = CHK.ORDER_CODE INNER JOIN OP_SELLER S ON OI.SELLER_ID = S.SELLER_ID
AND OI.SELLER_ID = #{sellerId} AND OI.DELIVERY_TYPE = '2'
AND OI.ORDER_STATUS IN
#{status}
AND OI.SELLER_ID = #{sellerId}
AND OI.SELLER_ID > #{sellerId}
AND OI.DELIVERY_TYPE = #{deliveryType}
AND OI.ORDER_STATUS IN
#{status}
AND OI.ORDER_CODE IN
#{orderCode}
AND OI.ORDER_CODE = #{orderCode}
AND OI.ORDER_SEQUENCE = #{orderSequence}
AND OI.ITEM_SEQUENCE = #{itemSequence}
AND OI.ORDER_STATUS IN
#{orderStatus}
AND OI.ORDER_STATUS = #{orderStatus}
AND OI.CANCEL_FLAG = #{cancelFlag}
AND OI.USER_ID = #{userId} AND OI.GUEST_FLAG = 'N'
AND OI.GUEST_FLAG = 'Y' AND O.BUYER_NAME = #{guestUserName} AND O.MOBILE = #{guestPhoneNumber}
AND S.LOCGOV_CODE = #{locgovCode}
AND S.LOCGOV_CODE LIKE CONCAT(SUBSTR(#{upperLocgovCode}, 0, 2), '%')
AND OI.ITEM_NAME LIKE CONCAT('%', #{itemName}, '%')
AND DATE_FORMAT(OI.CREATED_DATE, '%Y%m%d%H') BETWEEN CONCAT(#{searchStartDate},#{searchStartDateTime}) AND CONCAT(#{searchEndDate},#{searchEndDateTime})
AND DATE_FORMAT(O.CREATED_DATE, '%Y%m%d%H') BETWEEN CONCAT(#{searchStartDate},#{searchStartDateTime}) AND CONCAT(#{searchEndDate},#{searchEndDateTime})
AND DATE_FORMAT(#{searchDateType}, '%Y%m%d') BETWEEN #{searchStartDate} AND #{searchEndDate}
AND U.user_name LIKE CONCAT('%', #{query}, '%')
AND OI.USER_ID IN ( SELECT USER_ID FROM OP_USER WHERE LOGIN_ID LIKE CONCAT('%', #{query},'%') )
AND ( REPLACE(OSI.PHONE, '-', '') LIKE CONCAT(REPLACE(#{query}, '-', ''), '%') OR REPLACE(OSI.MOBILE, '-', '') LIKE CONCAT(REPLACE(#{query}, '-', ''), '%') )
AND OSI.RECEIVE_NAME LIKE CONCAT('%', #{query},'%')
AND OI.ITEM_NAME LIKE CONCAT('%', #{query},'%')
AND (OI.ITEM_CODE = #{query} OR OI.ITEM_USER_CODE = #{query})
AND OSI.EMAIL LIKE CONCAT(#{query}, '%')
AND OI.ORDER_CODE LIKE CONCAT('%', #{query} , '%')
AND S.COMPANY_NAME LIKE CONCAT('%', #{query},'%')
AND OI.LOCGOV_CODE = #{shLocgovCode}
AND OI.LOCGOV_CODE IN ( SELECT LOCGOV.LOCGOV_CODE FROM G_LOCGOV LOCGOV WHERE LOCGOV.UPPER_LOCGOV_CODE = #{shWdr} )
AND CHK.MATCH_YN = 'Y' AND OI.FILLER10 = 'N'
AND NOT EXISTS (SELECT 1 FROM OP_ORDER_ITEM T WHERE T.ORDER_CODE = OI.ORDER_CODE AND T.ORDER_SEQUENCE = OI.ORDER_SEQUENCE AND T.ITEM_SEQUENCE = OI.ITEM_SEQUENCE)
AND OI.HOLD_CONFIRM_STATUS IN
#{status}
ORDER BY OI.ORDER_CODE DESC
) OI LEFT OUTER JOIN OP_USER U ON OI.OI_USER_ID = U.USER_ID LEFT OUTER JOIN G_LOCGOV L ON L.LOCGOV_CODE = OI.LOCGOV_CODE

/* saleson.shop.tempprocess.TempProcessMapper.getTempRemittanceConfirmListByParam */
SELECT S.*, T.LOCGOV_CODE,
(SELECT UPPER_LOCGOV_NM || ' ' || LOCGOV_NM FROM G_LOCGOV L WHERE L.LOCGOV_CODE = T.LOCGOV_CODE) AS LOCGOV_NM, T.REMITTANCE_DATE, T.CANCEL_FLAG, T.REMITTANCE_STATUS_CODE, T.PRODUCT_TYPE, T.ITEM_TOTAL_COMMISSION_BASE_AMOUNT, T.ITEM_TOTAL_COMMISSION_AMOUNT, T.ITEM_TOTAL_SUPPLY_AMOUNT, T.ITEM_TOTAL_SELLER_DISCOUNT_AMOUNT, T.ITEM_TOTAL_SELLER_POINT_AMOUNT, T.ITEM_TOTAL_SET_DISCOUNT_AMOUNT, T.SHIPPING_TOTAL_AMOUNT, T.ADD_PAYMENT_TOTAL_AMOUNT, T.CANCEL_ITEM_TOTAL_SUPPLY_AMOUNT, T.CANCEL_SHIPPING_TOTAL_AMOUNT FROM ( SELECT G.SELLER_ID, G.LOCGOV_CODE,
G.REMITTANCE_DATE, G.CANCEL_FLAG, G.REMITTANCE_STATUS_CODE, G.PRODUCT_TYPE, SUM(G.ITEM_TOTAL_COMMISSION_BASE_AMOUNT) AS ITEM_TOTAL_COMMISSION_BASE_AMOUNT, SUM(G.ITEM_TOTAL_COMMISSION_AMOUNT) AS ITEM_TOTAL_COMMISSION_AMOUNT, SUM(G.ITEM_TOTAL_SUPPLY_AMOUNT) AS ITEM_TOTAL_SUPPLY_AMOUNT, SUM(G.ITEM_TOTAL_SELLER_DISCOUNT_AMOUNT) AS ITEM_TOTAL_SELLER_DISCOUNT_AMOUNT, SUM(G.ITEM_TOTAL_SELLER_POINT_AMOUNT) AS ITEM_TOTAL_SELLER_POINT_AMOUNT, SUM(G.ITEM_TOTAL_SET_DISCOUNT_AMOUNT) AS ITEM_TOTAL_SET_DISCOUNT_AMOUNT, SUM(G.SHIPPING_TOTAL_AMOUNT) AS SHIPPING_TOTAL_AMOUNT, SUM(G.ADD_PAYMENT_TOTAL_AMOUNT) AS ADD_PAYMENT_TOTAL_AMOUNT, SUM(G.CANCEL_ITEM_TOTAL_SUPPLY_AMOUNT) AS CANCEL_ITEM_TOTAL_SUPPLY_AMOUNT, SUM(G.CANCEL_SHIPPING_TOTAL_AMOUNT) AS CANCEL_SHIPPING_TOTAL_AMOUNT FROM ( SELECT M.SELLER_ID, M.LOCGOV_CODE,
M.REMITTANCE_DATE, M.CANCEL_FLAG, M.REMITTANCE_STATUS_CODE, M.PRODUCT_TYPE, (CASE WHEN M.PRODUCT_TYPE = 'ITEM' THEN TOTAL_COMMISSION_BASE_AMOUNT ELSE 0 END) AS ITEM_TOTAL_COMMISSION_BASE_AMOUNT, (CASE WHEN M.PRODUCT_TYPE = 'ITEM' THEN TOTAL_COMMISSION_AMOUNT ELSE 0 END) AS ITEM_TOTAL_COMMISSION_AMOUNT, (CASE WHEN M.PRODUCT_TYPE = 'ITEM' THEN TOTAL_SUPPLY_AMOUNT ELSE 0 END) AS ITEM_TOTAL_SUPPLY_AMOUNT, (CASE WHEN M.PRODUCT_TYPE = 'ITEM' THEN TOTAL_SELLER_DISCOUNT_AMOUNT ELSE 0 END) AS ITEM_TOTAL_SELLER_DISCOUNT_AMOUNT, (CASE WHEN M.PRODUCT_TYPE = 'ITEM' THEN TOTAL_SELLER_POINT_AMOUNT ELSE 0 END) AS ITEM_TOTAL_SELLER_POINT_AMOUNT, (CASE WHEN M.PRODUCT_TYPE = 'ITEM' THEN TOTAL_SET_DISCOUNT_AMOUNT ELSE 0 END) AS ITEM_TOTAL_SET_DISCOUNT_AMOUNT, (CASE WHEN M.PRODUCT_TYPE = 'SHIPPING' THEN TOTAL_COMMISSION_BASE_AMOUNT ELSE 0 END) AS SHIPPING_TOTAL_AMOUNT, (CASE WHEN M.PRODUCT_TYPE = 'ADD_PAYMENT' THEN TOTAL_COMMISSION_BASE_AMOUNT ELSE 0 END) AS ADD_PAYMENT_TOTAL_AMOUNT,
(CASE WHEN M.PRODUCT_TYPE = 'ITEM' AND M.CANCEL_FLAG = 'Y' AND M.REMITTANCE_STATUS_CODE = '1' THEN TOTAL_COMMISSION_BASE_AMOUNT ELSE 0 END) AS CANCEL_ITEM_TOTAL_SUPPLY_AMOUNT, (CASE WHEN M.PRODUCT_TYPE = 'SHIPPING' AND M.CANCEL_FLAG = 'Y' AND M.REMITTANCE_STATUS_CODE = '1' THEN TOTAL_COMMISSION_BASE_AMOUNT ELSE 0 END) AS CANCEL_SHIPPING_TOTAL_AMOUNT FROM (
SELECT OI.SELLER_ID, S.LOCGOV_CODE, OI.REMITTANCE_DATE, OI.CANCEL_FLAG, OI.REMITTANCE_STATUS_CODE, 'ITEM' AS PRODUCT_TYPE, SUM((CASE WHEN OI.CANCEL_FLAG = 'N' THEN OI.COMMISSION_BASE_PRICE ELSE -OI.COMMISSION_BASE_PRICE END) * OI.QUANTITY) AS TOTAL_COMMISSION_BASE_AMOUNT, SUM((CASE WHEN OI.CANCEL_FLAG = 'N' THEN OI.COMMISSION_PRICE ELSE -OI.COMMISSION_PRICE END) * OI.QUANTITY) AS TOTAL_COMMISSION_AMOUNT, SUM((CASE WHEN OI.CANCEL_FLAG = 'N' THEN OI.SUPPLY_PRICE ELSE -OI.SUPPLY_PRICE END) * OI.QUANTITY) AS TOTAL_SUPPLY_AMOUNT, SUM((CASE WHEN OI.CANCEL_FLAG = 'N' THEN 1 ELSE -1 END) * (OI.SELLER_DISCOUNT_PRICE + (CASE WHEN OI.SPOT_TYPE = '2' THEN OI.SPOT_DISCOUNT_PRICE ELSE 0 END)) * OI.QUANTITY) AS TOTAL_SELLER_DISCOUNT_AMOUNT, SUM((CASE WHEN OI.CANCEL_FLAG = 'N' THEN OI.SELLER_POINT ELSE -OI.SELLER_POINT END) * OI.QUANTITY) AS TOTAL_SELLER_POINT_AMOUNT, SUM((CASE WHEN OI.CANCEL_FLAG = 'N' THEN OI.SET_DISCOUNT_PRICE ELSE -OI.SET_DISCOUNT_PRICE END) * OI.QUANTITY) AS TOTAL_SET_DISCOUNT_AMOUNT FROM OP_ORDER_ITEM OI INNER JOIN OP_ORDER O ON OI.ORDER_CODE = O.ORDER_CODE AND OI.ORDER_SEQUENCE = O.ORDER_SEQUENCE AND O.DATA_STATUS_CODE = '1' JOIN OP_SELLER S ON S.SELLER_ID = OI.SELLER_ID
AND OI.SELLER_ID != #{defaultOpmanagerSellerId}
AND OI.SELLER_ID = #{sellerId}
AND REMITTANCE_STATUS_CODE = '0'
AND OI.REMITTANCE_DATE BETWEEN #{startDate} AND #{endDate}
AND OI.REMITTANCE_DATE BETWEEN CONCAT(LEFT(#{startDate}, 6), '00') AND CONCAT(LEFT(#{endDate}, 6), '99')
AND OI.REMITTANCE_DATE = #{startDate}
AND S.LOCGOV_CODE = #{shLocgovCode}
AND S.LOCGOV_CODE IN ( SELECT LOCGOV_CODE FROM G_LOCGOV WHERE UPPER_LOCGOV_CODE = #{shWdr} )
AND OI.SUPPLY_PRICE > 0
GROUP BY OI.SELLER_ID, OI.REMITTANCE_DATE, OI.CANCEL_FLAG
UNION ALL
SELECT OS.SELLER_ID, S.LOCGOV_CODE, OS.REMITTANCE_DATE, 'N' AS CANCEL_FLAG, OS.REMITTANCE_STATUS_CODE, 'SHIPPING' AS PRODUCT_TYPE, SUM(CASE WHEN OS.RETURN_FLAG = 'N' THEN OS.REMITTANCE_AMOUNT ELSE -OS.REMITTANCE_AMOUNT END) AS TOTAL_COMMISSION_BASE_AMOUNT, 0 AS TOTAL_COMMISSION_AMOUNT, 0 AS TOTAL_SUPPLY_AMOUNT, 0 AS TOTAL_SELLER_DISCOUNT_AMOUNT, 0 AS TOTAL_SELLER_POINT_AMOUNT, 0 AS TOTAL_SET_DISCOUNT_AMOUNT FROM OP_ORDER_SHIPPING OS INNER JOIN OP_ORDER O ON OS.ORDER_CODE = O.ORDER_CODE AND OS.ORDER_SEQUENCE = O.ORDER_SEQUENCE AND O.DATA_STATUS_CODE = '1' JOIN OP_SELLER S ON S.SELLER_ID = OS.SELLER_ID
AND OS.SELLER_ID != #{defaultOpmanagerSellerId}
AND OS.SELLER_ID = #{sellerId}
AND REMITTANCE_STATUS_CODE = '0'
AND OS.REMITTANCE_DATE BETWEEN #{startDate} AND #{endDate}
AND OS.REMITTANCE_DATE BETWEEN CONCAT(LEFT(#{startDate}, 6), '00') AND CONCAT(LEFT(#{endDate}, 6), '99')
AND OS.REMITTANCE_DATE = #{startDate}
AND OS.REMITTANCE_AMOUNT > 0
GROUP BY OS.SELLER_ID, OS.REMITTANCE_DATE
UNION ALL
SELECT OAP.SELLER_ID, S.LOCGOV_CODE, OAP.REMITTANCE_DATE, 'N' AS CANCEL_FLAG, OAP.REMITTANCE_STATUS_CODE, 'ADD_PAYMENT' AS PRODUCT_TYPE, SUM(CASE WHEN OAP.ADD_PAYMENT_TYPE = '1' THEN OAP.REMITTANCE_AMOUNT ELSE -OAP.REMITTANCE_AMOUNT END) AS TOTAL_COMMISSION_BASE_AMOUNT, 0 AS TOTAL_COMMISSION_AMOUNT, 0 AS TOTAL_SUPPLY_AMOUNT, 0 AS TOTAL_SELLER_DISCOUNT_AMOUNT, 0 AS TOTAL_SELLER_POINT_AMOUNT, 0 AS TOTAL_SET_DISCOUNT_AMOUNT FROM OP_ORDER_ADD_PAYMENT OAP INNER JOIN OP_ORDER O ON OAP.ORDER_CODE = O.ORDER_CODE AND OAP.ORDER_SEQUENCE = O.ORDER_SEQUENCE AND O.DATA_STATUS_CODE = '1' JOIN OP_SELLER S ON S.SELLER_ID = OAP.SELLER_ID
AND OAP.SELLER_ID != #{defaultOpmanagerSellerId}
AND OAP.SELLER_ID = #{sellerId}
AND REMITTANCE_STATUS_CODE = '0'
AND OAP.REMITTANCE_DATE BETWEEN #{startDate} AND #{endDate}
AND OAP.REMITTANCE_DATE BETWEEN CONCAT(LEFT(#{startDate}, 6), '00') AND CONCAT(LEFT(#{endDate}, 6), '99')
AND OAP.REMITTANCE_DATE = #{startDate}
AND OAP.REMITTANCE_AMOUNT > 0
GROUP BY OAP.SELLER_ID, OAP.REMITTANCE_DATE ) M ) G GROUP BY G.SELLER_ID, G.REMITTANCE_DATE ) T INNER JOIN OP_SELLER S ON T.SELLER_ID = S.SELLER_ID

/* saleson.shop.tempprocess.TempProcessMapper.getOrderByParam */ SELECT ( SELECT UPPER_LOCGOV_NM || ' ' || LOCGOV_NM FROM G_LOCGOV WHERE LOCGOV_CODE = S.LOCGOV_CODE ) AS LOCGOV_NM, S.LOCGOV_CODE,
U.USER_NAME, ( SELECT PHONE_NUMBER FROM OP_USER_DETAIL U2 WHERE U2.USER_ID = U.USER_ID) AS MOBILE, U.LOGIN_ID, U.EMAIL, U.USER_ID,
OI.ORDER_CODE, OI.ORDER_SEQUENCE, OI.ITEM_SEQUENCE, OI.ORDER_STATUS, OI.SHIPPING_SEQUENCE, OI.ADDITION_ITEM_FLAG, OI.PARENT_ITEM_SEQUENCE, OI.DEVICE_TYPE, OI.GUEST_FLAG, OI.SELLER_ID, OI.CATEGORY_TEAM_ID, OI.CATEGORY_GROUP_ID, OI.CATEGORY_ID, OI.SHIPMENT_ID, OI.COUPON_USER_ID, OI.ADD_COUPON_USER_ID, OI.ITEM_ID, OI.ITEM_CODE, OI.ITEM_USER_CODE, OI.ITEM_NAME, OI.FREE_GIFT_NAME, OI.IMAGE_SRC, OI.SHIPPING_RETURN, OI.PURCHASE_PRICE, OI.COST_PRICE, OI.PRICE, OI.OPTION_PRICE, OI.SALE_PRICE, OI.QUANTITY, OI.CLAIM_QUANTITY, OI.ORDER_QUANTITY, OI.COUPON_DISCOUNT_PRICE, OI.SPOT_SALE_FLAG, OI.SPOT_TYPE, OI.SPOT_DISCOUNT_PRICE, OI.TAX_TYPE, OI.COMMISSION_RATE, OI.COMMISSION_BASE_PRICE, OI.COMMISSION_PRICE, OI.SUPPLY_PRICE, OI.SELLER_DISCOUNT_PRICE, OI.SELLER_DISCOUNT_DETAIL, OI.ADMIN_DISCOUNT_PRICE, OI.ADMIN_DISCOUNT_DETAIL, OI.BRAND, OI.OPTIONS, OI.DELIVERY_COMPANY_ID, OI.DELIVERY_COMPANY_NAME, OI.DELIVERY_COMPANY_URL, OI.DELIVERY_NUMBER, OI.SHIPMENT_RETURN_TYPE, OI.POINT_TYPE, OI.POINT_CONFIG_TYPE, OI.POINT, OI.POINT_LOG, OI.EARN_POINT, OI.EARN_POINT_FLAG, OI.SELLER_POINT, OI.PAY_DATE, OI.SHIPPING_READY_DATE, OI.SHIPPING_DATE, OI.SHIPPING_FINISH_DATE, OI.CANCEL_REQUEST_DATE, OI.CANCEL_REQUEST_FINISH_DATE, OI.SALES_DATE, OI.SALES_CANCEL_DATE, OI.CONFIRM_DATE, OI.RETURN_REQUEST_DATE, OI.EXCHANGE_REQUEST_DATE, OI.RETURN_REQUEST_FINISH_DATE, OI.RETURN_POINT_FLAG, OI.CREATED_DATE, OI.SHIPMENT_RETURN_ID, OI.CANCEL_FLAG, OI.REFUND_STATUS, OI.ITEM_RETURN_FLAG, OI.DELIVERY_TYPE, OI.REMITTANCE_ID, OI.REMITTANCE_TYPE, OI.REMITTANCE_DAY, OI.ESCROW_STATUS, OI.LEVEL_ID, OI.LEVEL_NAME, OI.USER_LEVEL_DISCOUNT_RATE, OI.USER_LEVEL_DISCOUNT_PRICE,
OI.SET_ITEM_FLAG, OI.SET_DISCOUNT_TYPE, IFNULL(OI.SET_DISCOUNT_PRICE, 0) AS SET_DISCOUNT_PRICE,
OSI.SHIPPING_INFO_SEQUENCE, OSI.RECEIVE_ZIPCODE, OSI.RECEIVE_NEW_ZIPCODE, OSI.RECEIVE_SIDO, OSI.RECEIVE_SIGUNGU, OSI.RECEIVE_EUPMYEONDONG, OSI.RECEIVE_ADDRESS, OSI.RECEIVE_ADDRESS_DETAIL, OSI.RECEIVE_NAME, OSI.RECEIVE_PHONE, OSI.RECEIVE_MOBILE, OSI.MEMO,
OS.SELLER_ID AS SHIPPING_SELLER_ID, OS.SHIPPING_TYPE, OS.SHIPMENT_GROUP_CODE, OS.SHIPPING_GROUP_CODE, OS.ISLAND_TYPE, OS.SHIPPING_ITEM_COUNT, OS.SHIPPING, OS.SHIPPING_EXTRA_CHARGE1, OS.SHIPPING_EXTRA_CHARGE2, OS.SHIPPING_FREE_AMOUNT, OS.REAL_SHIPPING, OS.DISCOUNT_SHIPPING, OS.SHIPPING_COUPON_COUNT, OS.SHIPPING_PAYMENT_TYPE, OS.PAY_SHIPPING, OS.RETURN_SHIPPING, OS.REMITTANCE_AMOUNT, OS.REMITTANCE_DATE, ( CASE WHEN ( SELECT MIN(ITEM_SEQUENCE) FROM OP_ORDER_ITEM WHERE ORDER_CODE = OI.ORDER_CODE AND ORDER_SEQUENCE = OI.ORDER_SEQUENCE AND SHIPPING_SEQUENCE = OI.SHIPPING_SEQUENCE ) = OI.ITEM_SEQUENCE THEN 'Y' ELSE 'N' END ) AS IS_SHIPPING_VIEW, S.COMPANY_NAME, S.SELLER_NAME, OSI.CREATED_DATE AS ORDER_INFO_CREATED_DATE, OSI.UPDATED_DATE AS ORDER_INFO_UPDATED_DATE,
CASE WHEN OI.CAMPAIGN_CODE = 'MOBILE' THEN 'Y' ELSE 'N' END AS MOBILE_ITEM_YN, OI.PAY_DATE, (SELECT CLAIM_STATUS FROM OP_ORDER_CANCEL_APPLY WHERE ORDER_CODE = OI.ORDER_CODE AND ORDER_SEQUENCE = OI.ORDER_SEQUENCE AND ITEM_SEQUENCE = OI.ITEM_SEQUENCE ORDER BY CLAIM_CODE DESC LIMIT 1) AS CANCEL_CLAIM_STATUS, (SELECT CANCEL_REFUSAL_REASON_TEXT FROM OP_ORDER_CANCEL_APPLY WHERE ORDER_CODE = OI.ORDER_CODE AND ORDER_SEQUENCE = OI.ORDER_SEQUENCE AND ITEM_SEQUENCE = OI.ITEM_SEQUENCE ORDER BY CLAIM_CODE DESC LIMIT 1) AS CANCEL_REFUSAL_REASON_TEXT FROM OP_ORDER_ITEM_HOLD OI
INNER JOIN OP_ORDER_SHIPPING_INFO OSI ON OI.ORDER_CODE = OSI.ORDER_CODE AND OI.ORDER_SEQUENCE = OSI.ORDER_SEQUENCE AND OI.SHIPPING_INFO_SEQUENCE = OSI.SHIPPING_INFO_SEQUENCE
INNER JOIN OP_ORDER_SHIPPING OS ON OI.ORDER_CODE = OS.ORDER_CODE AND OI.ORDER_SEQUENCE = OS.ORDER_SEQUENCE AND OI.SHIPPING_SEQUENCE = OS.SHIPPING_SEQUENCE
LEFT JOIN OP_SELLER S ON OI.SELLER_ID = S.SELLER_ID INNER JOIN OP_ITEM ITEM ON OI.ITEM_ID = ITEM.ITEM_ID LEFT JOIN OP_USER U ON U.USER_ID = OI.USER_ID WHERE OI.ORDER_CODE = #{orderCode} AND OI.ORDER_SEQUENCE = #{orderSequence}
AND OI.SELLER_ID = #{sellerId}
AND OI.SELLER_ID = #{sellerId}
AND OI.USER_ID = #{userId} AND OI.GUEST_FLAG = 'N'
AND OI.SESSION_ID = #{sessionId}
AND OI.GUEST_FLAG = 'Y'
ORDER BY S.LOCGOV_CODE ASC, OI.ORDER_SEQUENCE ASC, OI.SHIPPING_INFO_SEQUENCE ASC, OI.ITEM_SEQUENCE ASC

/* saleson.shop.tempprocess.TempProcessMapper.getTempRemittanceConfirmCountByParamNew */
SELECT
		COUNT(1)
	FROM OP_REMITTANCE R
	JOIN OP_SELLER S ON R.SELLER_ID = S.SELLER_ID
	WHERE 1=1

		AND R.SELLER_ID != #{defaultOpmanagerSellerId}



		AND R.SELLER_ID = #{sellerId}


	AND R.REMITTANCE_STATUS_CODE = '0'



			AND S.REPRESENTATIVE_NAME = #{query}


			AND S.COMPANY_NAME LIKE CONCAT('%', #{query}, '%')






				AND R.CONFIRM_DATE BETWEEN #{startDate} AND #{endDate}




				AND R.REMITTANCE_YM BETWEEN LEFT(#{startDate}, 6) AND LEFT(#{endDate}, 6)






			AND S.LOCGOV_CODE = #{shLocgovCode}



				AND S.LOCGOV_CODE IN (
					SELECT LOCGOV_CODE FROM G_LOCGOV WHERE UPPER_LOCGOV_CODE = #{shWdr}
				)

/* saleson.shop.tempprocess.TempProcessMapper.getTempRemittanceConfirmListByParamNew */
SELECT S.* , R.REMITTANCE_STATUS_CODE , R.CONFIRM_DATE , R.CONFIRM_DATE_SELLER , R.PAYMENT_DATE , R.FINISHING_DATE , R.FINISHING_AMOUNT , R.REMITTANCE_YM , (SELECT UPPER_LOCGOV_NM || ' ' || LOCGOV_NM FROM G_LOCGOV L WHERE L.LOCGOV_CODE = S.LOCGOV_CODE) AS LOCGOV_NM , RD.* , (SELECT COUNT(1) FROM G_REMITTANCE_FILE RF WHERE RF.REMITTANCE_ID = R.REMITTANCE_ID ) AS FILE_CNT FROM ( SELECT REMITTANCE_ID , SUM(COMMISSION_BASE_PRICE * QUANTITY + ETC_AMT) AS ITEM_TOTAL_COMMISSION_BASE_AMOUNT , SUM(COMMISSION_PRICE * QUANTITY + ETC_AMT) AS ITEM_TOTAL_COMMISSION_AMOUNT , SUM(SUPPLY_PRICE * QUANTITY + ETC_AMT) AS ITEM_TOTAL_SUPPLY_AMOUNT , SUM(SELLER_DISCOUNT_PRICE * QUANTITY) AS ITEM_TOTAL_SELLER_DISCOUNT_AMOUNT , SUM(SELLER_POINT * QUANTITY) AS ITEM_TOTAL_SELLER_POINT_AMOUNT , SUM(SET_DISCOUNT_PRICE * QUANTITY) AS ITEM_TOTAL_SET_DISCOUNT_AMOUNT FROM OP_REMITTANCE_DETAIL GROUP BY REMITTANCE_ID ) RD JOIN OP_REMITTANCE R ON R.REMITTANCE_ID = RD.REMITTANCE_ID JOIN OP_SELLER S ON R.SELLER_ID = S.SELLER_ID WHERE 1=1
AND R.SELLER_ID != #{defaultOpmanagerSellerId}
AND R.SELLER_ID = #{sellerId}
AND R.REMITTANCE_STATUS_CODE = '0'
AND S.REPRESENTATIVE_NAME = #{query}
AND S.COMPANY_NAME LIKE CONCAT('%', #{query}, '%')
AND R.REMITTANCE_YM BETWEEN LEFT(#{startDate}, 6) AND LEFT(#{endDate}, 6)
AND R.CONFIRM_DATE BETWEEN #{startDate} AND #{endDate}
AND S.LOCGOV_CODE = #{shLocgovCode}
AND S.LOCGOV_CODE IN ( SELECT LOCGOV_CODE FROM G_LOCGOV WHERE UPPER_LOCGOV_CODE = #{shWdr} )
ORDER BY R.CONFIRM_DATE DESC
ORDER BY R.REMITTANCE_YM DESC

/* saleson.shop.tempprocess.TempProcessMapper.getTempRemittanceConfirmDetailList */
SELECT RD.ORDER_CODE , RD.ORDER_SEQUENCE , RD.ITEM_SEQUENCE , RD.REMITTANCE_DETAIL_ID , RD.ORDER_CODE , RD.REMITTANCE_KEY , RD.ITEM_TYPE , RD.ITEM_USER_CODE , RD.ITEM_NAME , RD.OPTIONS , RD.SALE_PRICE , RD.COMMISSION_BASE_PRICE , RD.REMITTANCE_PRICE , RD.QUANTITY , RD.ETC_AMT , OI.ORDER_SEQUENCE , R.REMITTANCE_STATUS_CODE , R.REMITTANCE_ID , R.CONFIRM_DATE AS REMITTANCE_DATE , OI.USER_ID , TO_CHAR(U.USER_NAME) AS BUYER_NAME , OI.PAY_DATE , OI.CONFIRM_DATE , OI.SELLER_ID FROM OP_REMITTANCE_DETAIL RD JOIN OP_REMITTANCE R ON R.REMITTANCE_ID = RD.REMITTANCE_ID LEFT JOIN OP_ORDER_ITEM OI ON RD.ORDER_CODE = OI.ORDER_CODE AND RD.ITEM_SEQUENCE = OI.ITEM_SEQUENCE AND OI.ORDER_SEQUENCE = RD.ORDER_SEQUENCE AND RD.ITEM_TYPE = 'ITEM' LEFT JOIN OP_USER U ON OI.USER_ID = U.USER_ID WHERE 1 = 1
AND RD.ORDER_CODE LIKE CONCAT('%', #{query} , '%')
AND U.USER_NAME = #{query}
AND RD.ITEM_USER_CODE LIKE CONCAT('%', #{query} , '%')
AND RD.ITEM_NAME LIKE CONCAT('%', #{query} , '%')
AND OI.SELLER_ID != #{defaultOpmanagerSellerId}
AND OI.SELLER_ID = #{sellerId}
AND R.REMITTANCE_ID = #{remittanceId} AND R.REMITTANCE_STATUS_CODE = '0'
ORDER BY RD.ORDER_CODE DESC

/* saleson.shop.tempprocess.TempProcessMapper.getTempRemittanceConfirmDetailCountByParamNew */

SELECT
		COUNT(1)
			FROM OP_REMITTANCE_DETAIL RD
		JOIN OP_REMITTANCE R ON R.REMITTANCE_ID = RD.REMITTANCE_ID
		LEFT JOIN OP_ORDER_ITEM OI ON RD.ORDER_CODE = OI.ORDER_CODE AND RD.ITEM_SEQUENCE = OI.ITEM_SEQUENCE AND OI.ORDER_SEQUENCE = RD.ORDER_SEQUENCE AND RD.ITEM_TYPE = 'ITEM'



					LEFT JOIN OP_USER U ON OI.USER_ID = U.USER_ID



		WHERE 1 = 1



						AND RD.ORDER_CODE LIKE CONCAT('%', #{query} , '%')


						AND U.USER_NAME = #{query}


						AND RD.ITEM_USER_CODE LIKE CONCAT('%', #{query} , '%')


						AND RD.ITEM_NAME LIKE CONCAT('%', #{query} , '%')





				AND OI.SELLER_ID != #{defaultOpmanagerSellerId}



				AND OI.SELLER_ID = #{sellerId}

			AND R.REMITTANCE_STATUS_CODE = '0'

			AND R.REMITTANCE_ID = #{remittanceId}

mapper.update:
