/* saleson.shop.tempprocess.TempProcessMapper.updateHoldOrderListByParam */
UPDATE OP_ORDER_ITEM_HOLD
SET    HOLD_CONFIRM_STATUS = #{inputStatus}

	, HOLD_CONFIRM_DATE_SELLER = #{holdConfirmDate}
	, HOLID_CONFIRM_SELLER_USER_ID = #{holidConfirmUserId}


	, HOLD_CONFIRM_DATE_MGR = #{holdConfirmDate}
	, HOLID_CONFIRM_MGR_ID = #{holidConfirmUserId}


	, HOLD_REJECT_DATE_MGR = #{holdConfirmDate}
	, HOLID_REJECT_MGR_ID = #{holidConfirmUserId}

WHERE 1=1
AND   ORDER_CODE = #{orderCode}
AND   FILLER5 = #{filler5}

mapper.insert:
/* saleson.shop.tempprocess.TempProcessMapper.insertHoldOrderListLog */ INSERT INTO OP_ORDER_ITEM_HOLD_HIST SELECT (SELECT IFNULL(MAX(REG_SEQ), 0) + 1 FROM OP_ORDER_ITEM_HOLD_HIST) AS REG_SEQ , ORDER_CODE , ORDER_SEQUENCE , ITEM_SEQUENCE , HOLD_CONFIRM_STATUS AS HOLD_CONFRIM_STATUS_BEF , #{inputStatus} AS HOLD_CONFRIM_STATUS_AFT
, 'S' AS CREATED_USER_TP
, 'M' AS CREATED_USER_TP
, #{holidConfirmUserId} AS CREATED_USER_ID , TO_CHAR(CURRENT_DATETIME(), 'YYYYMMDDHH24MISS') AS CREATED_DATE FROM OP_ORDER_ITEM_HOLD WHERE 1=1 AND ORDER_CODE = #{orderCode} AND FILLER5 = #{filler5}

mapper.select:
