	, ORDER_CODE
	, ORDER_SEQUENCE
	, ITEM_SEQUENCE
FROM OP_ORDER_ITEM_HOLD
	WHERE 1=1
	AND   ORDER_CODE = #{orderCode}
	AND   FILLER5 = #{filler5}
